#!/usr/bin/env python3
import os, json, sys, numpy as np

# Physical constants (SI)
G = 6.67430e-11            # m^3 kg^-1 s^-2
c = 2.99792458e8          # m s^-1
M_sun = 1.98847e30        # kg

def load_catalog(path):
    """Load a GWTC catalog JSON file.
    Returns a list of event dictionaries if successful, otherwise raises ValueError.
    """
    try:
        with open(path, 'r') as f:
            data = json.load(f)
        events = data.get('events', [])
        if not isinstance(events, list):
            raise ValueError('Events are not a list')
        return events
    except Exception as e:
        sys.stderr.write(f"Error reading catalog at {path}: {e}\n")
        sys.exit(1)

def compute_fraction(event):
    m1 = event.get('mass_1_source')
    m2 = event.get('mass_2_source')
    mc = event.get('final_mass_source')
    if None in (m1, m2, mc):
        return None
    try:
        m1 = float(m1)
        m2 = float(m2)
        mc = float(mc)
    except (ValueError, TypeError):
        return None
    if m1 <= 0 or m2 <= 0 or mc <= 0:
        return None
    total_initial = m1 + m2
    loss = (total_initial - mc) / total_initial
    if loss < 0:
        loss = 0.0
    return loss

def main():
    catalog_path = os.getenv('GWTC_CATALOG_PATH')
    if not catalog_path:
        sys.stderr.write('Error: GWTC_CATALOG_PATH environment variable not set.\n')
        sys.exit(1)
    events = load_catalog(catalog_path)
    failures = []
    for ev in events:
        loss = compute_fraction(ev)
        if loss is not None and loss > 0.25:
            failures.append((ev.get('event'), loss))
    if not failures:
        print('PASS: No event violates the 25% radiated‑mass bound.')
        sys.exit(0)
    print('FAIL: Events exceeding the 25% bound:')
    for name, val in failures:
        print(f'  {name}: {val:.4f}')
    sys.exit(1)

if __name__ == '__main__':
    main()

