#!/usr/bin/env python3
import math, json, os, sys, random, statistics

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def geometric_mass(m_kg):
    """Convert a mass in kg to its geometric length (meters) in 4‑D spacetime.
    In geometric units the mass length is M = G * m / c^2.
    """
    return G * m_kg / c**2

def mass_in_grams(m_geom_m):
    """Convert a geometric mass length (meters) back to kg via M = c^2 / (G * m)."""
    return c**2 / (G * m_geom_m)

def random_spin(axis, max_a):
    """Generate a random Kerr spin parameter a (meters) along *axis*.
    *axis* can be "x", "y", or "z" – the chosen component is set, others are zero.
    """
    a = random.uniform(-max_a, max_a)
    if axis == "x":
        return (a, 0.0, 0.0)
    elif axis == "y":
        return (0.0, a, 0.0)
    else:
        return (0.0, 0.0, a)

def horizon_radius(M_geom, a_geom):
    """Kerr outer horizon radius r_+ = M + sqrt(M^2 - a^2)."""
    return M_geom + math.sqrt(M_geom**2 - a_geom**2)

def horizon_area(r_hor, theta):
    """Area of a spherical horizon piece: 2π r^2 (1 - cosθ)^2."""
    return 2 * math.pi * r_hor**2 * (1 - math.cos(theta))**2

def random_azimuth():
    """Random azimuthal angle (radians) between 0 and 2π."""
    return random.uniform(0, 2 * math.pi)

def random_cos_theta():
    """Random cosine of the polar angle, uniform in cosθ between -1 and 1."""
    return random.uniform(-1, 1)

def run(N=10000):
    # Define a fiducial black‑hole mass (10 solar masses) and a modest spin
    M_sun_kg = 10 * M_sun
    M_geom = geometric_mass(M_sun_kg)          # geometric mass length (meters)
    a_geom = 0.5 * M_geom                      # spin parameter (meters)

    # Acceptance‑rejection thresholds for the random test
    area_threshold = 0.05 * horizon_area(M_geom, a_geom)  # 5 % of total horizon area
    area_accept = 0.0
    area_reject = 0.0
    area_sum = 0.0

    for _ in range(N):
        # Random azimuthal angle
        phi = random_azimuth()
        # Random cosine of the polar angle, then compute r and area of the spherical strip
        cos_theta = random_cos_theta()
        sin_theta = math.sqrt(1 - cos_theta**2)
        r = M_geom * (1 + cos_theta)          # simple r(θ) for the test
        dA = horizon_area(r, math.pi / 2)    # area of a strip at constant r and θ
        area_sum += dA
        if dA < area_threshold:
            area_reject += dA
        else:
            area_accept += dA

    total_area = area_sum
    acceptance_rate = area_accept / total_area if total_area > 0 else 0.0
    print(f"Total horizon area (sum of strips): {total_area:.6e} m^2")
    print(f"Acceptance rate (A < threshold): {acceptance_rate:.4%}")

if __name__ == "__main__":
    run()
